function findHeadingLines(markdown, level) {
  const re = new RegExp(`^${'#'.repeat(level)}\\s+(.+?)\\s*$`, 'gm');
  const hits = [];
  let m;
  while ((m = re.exec(markdown)) !== null) {
    hits.push({ title: m[1], index: m.index });
  }
  return hits;
}

function sectionByExactHeading(markdown, headingLine) {
  // headingLine includes hashes, e.g. "## Email Excerpts"
  const escaped = headingLine.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const startRe = new RegExp(`^${escaped}\\s*$`, 'm');
  const startMatch = startRe.exec(markdown);
  if (!startMatch) return null;

  const startIdx = startMatch.index;
  const afterStartIdx = startIdx + startMatch[0].length;

  // Find next same-or-higher heading (## or #) after start.
  // Since all our top sections are ##, stop at next ##.
  const rest = markdown.slice(afterStartIdx);
  const nextRe = /^##\s+.+\s*$/m;
  const nextMatch = nextRe.exec(rest);
  const endIdx = nextMatch ? afterStartIdx + nextMatch.index : markdown.length;
  return markdown.slice(startIdx, endIdx);
}

module.exports = { sectionByExactHeading, findHeadingLines };
