    const subjectMatch = block.match(/^Subject:\s*Re:\s*(TXN-[0-9a-f-]+)\s*$/im);
    const statusMatch = block.match(/^status:\s*(\w+)\s*$/im);
    if (!fromMatch || !subjectMatch || !statusMatch) continue;

    const from_addr = fromMatch[1].trim();
    if (!/^compliance@/i.test(from_addr)) continue;

    const sentMatch = block.match(/^sent:\s*(\d{4}-\d{2}-\d{2})\s*$/im);

    emails.push({
      from_addr,
      transaction_id: subjectMatch[1],
      status: statusMatch[1].trim().toLowerCase(),
      sent: sentMatch ? sentMatch[1] : null,
    });
  }
  return emails;
}

function parseEmails(markdown) {
  const section = sectionByExactHeading(markdown, '## Email Excerpts');
  if (!section) return { amendments: [], compliance: [] };

  return {
    amendments: parseAmendments(section),
    compliance: parseComplianceEmails(section),
  };
}

module.exports = { parseEmails };
